indexes_data = json.loads(indexes_json)

# Write indexes - one file per index
index_count = 0
for table_data in indexes_data:
    tablename = table_data['tablename']
    all_indexes = table_data['all_indexes'].replace('\\n', '\n')
    
    # Split into individual index statements
    index_statements = [stmt.strip() for stmt in all_indexes.split(';') if stmt.strip()]
    
    for idx_stmt in index_statements:
        # Extract index name from statement
        # Pattern: CREATE [UNIQUE] INDEX indexname ON ...
        import re
        match = re.search(r'CREATE\s+(?:UNIQUE\s+)?INDEX\s+(\w+)', idx_stmt)
        if match:
            index_name = match.group(1)
            filename = f"{index_name}.sql"
            filepath = os.path.join('supabase/indexes', filename)
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(idx_stmt + ';')
            index_count += 1

print(f"Created {index_count} index files in supabase/indexes")

